window.AUTH=window.AUTH||{};window.AUTH["18-1432"]={"d":"18-1432","id":"2019/18-1432","n":"Nasrallah v. Barr","briefs":[{"k":"petitioner","label":"Brief of petitioner Nidal Khalid Nasrallah","date":"2019-12-09","url":"https://www.supremecourt.gov/DocketPDF/18/18-1432/124898/20191209135824866_18-1432.ts.brief.pdf","side":"pet","n":44},{"k":"respondent","label":"Brief of respondent William P. Barr, Attorney General","date":"2020-01-15","url":"https://www.supremecourt.gov/DocketPDF/18/18-1432/128810/20200115194839439_18-1432bsUnitedStates.pdf","side":"res","n":109},{"k":"reply","label":"Reply of petitioner Nidal Khalid Nasrallah","date":"2020-02-14","url":"https://www.supremecourt.gov/DocketPDF/18/18-1432/133024/20200214112724483_18-1432.reply.brief.pdf","side":"pet","n":42}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US2PP_web.pdf#page=161","tr":true,"items":[{"t":"case","label":"Albathani v. INS","cite":"318 F.3d 365","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/318/365/","by":{"0":"38"}},{"t":"case","label":"Ardestani v. INS","cite":"502 U.S. 129","y":1991,"id":"1991/90-1141","sc":1,"sum":"Administrative deportation proceedings are not adversary adjudications \"under section 554\" and thus do not fall within the category of proceedings for which the EAJA has waived sovereign immunity and authorized the award of attorney's fees and costs.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Arej v. Sessions","cite":"852 F.3d 665","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/852/665/","by":{"0":"39"}},{"t":"case","label":"Bowen v. Michigan Acad. of Family Physicians","cite":"476 U.S. 667","y":1986,"id":"1985/85-225","sc":1,"sum":"In neither 42 U. S. C. § 1395ff (1982 ed. and Supp. II) nor § 1395ii (1982 ed., Supp. II), has Congress barred judicial review of regulations promulgated under Part B of the Medicare program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36"}},{"t":"case","label":"Burgess v. United States","cite":"553 U.S. 124","y":2008,"id":"2007/06-11429","sc":1,"sum":"The Court upheld the sentencing hike, stating that the definition of a felony drug offense in 12 U.S.C. 841 as punishable by imprisonment for more than one year was controlling regardless of whether South Carolina classified the offense as a felony or a misdemeanor.","sumSrc":"Oyez","by":{"0":"26, 33","2":"6, 10, 12"}},{"t":"case","label":"Calcano-Martinez v. INS","cite":"533 U.S. 348","y":2001,"id":"2000/00-1011","sc":1,"op":2,"sum":"The Court held that the Court of Appeals lacked jurisdiction to hear the petitions for direct but petitioners can proceed with their habeas petitions if they wish to obtain relief. \"As petitioners in this case were convicted of 'aggravated felonies' within the meaning of the relevant statutes,\" wrote Justice Stevens, \"the plain language of [IIRIRA] fairly explicitly strips the courts of appeals of jurisdiction to hear their claims on petitions for direct review.\" Justice Stevens continued that \"Congress has not spoken with sufficient clarity to strip the district courts of jurisdiction to hear habeas petitions raising identical claims.\".","sumSrc":"Oyez","by":{"0":"3, 26","1":"2"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"0":"29, 30"}},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"136 S. Ct. 2131","y":2016,"id":"2015/15-446","sc":1,"sum":"The Court held that the Patent Trial and Appeal Board may apply the broadest reasonable interpretation of patent claims during an inter partes review proceeding, and such a proceeding is not judicially reviewable.","sumSrc":"Oyez","by":{"0":"37","1":"37"}},{"t":"case","label":"Cyan, Inc. v. Beaver Cty. Emps. Ret. Fund","cite":"138 S. Ct. 1061","y":2018,"id":"2017/15-1439","sc":1,"sum":"The Court held that that the Securities Litigation Uniform Standards Act of 1998 does not strip state courts of jurisdiction to hear claims under the Securities Act of 1933, nor does it permit defendants to remove class actions alleging only 1933 Act claims from state to federal court.","sumSrc":"Oyez","by":{"0":"24, 36"}},{"t":"case","label":"Digital Realty Tr., Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"0":"33","2":"10, 12"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"23","1":"16"}},{"t":"case","label":"Foti v. INS","cite":"375 U.S. 217","y":1963,"id":"1963/28","sc":1,"op":5,"ar":10,"sum":"Under § 106 (a) of the Immigration and Nationality Act, as added in 1961, a Federal Court of Appeals has sole and exclusive jurisdiction to review an administrative determination of the Attorney General denying a suspension of deportation sought by an alien under § 244 (a)(5). Pp. 217-232. 308 F.2d 779, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32, 33, 34","1":"passim","2":"passim"}},{"t":"case","label":"Guzman Chavez v. Hott","cite":"940 F.3d 867","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/940/867/","ar":1,"by":{"0":"8"}},{"t":"case","label":"Heller v. New York","cite":"413 U.S. 483","y":1973,"id":"1972/71-1043","sc":1,"sum":"Petitioner was manager of a movie theater where a sexually explicit film was exhibited. After police officers saw part of the film, an assistant district attorney requested a New York Criminal Court judge to view it. Upon seeing the entire performance, the judge signed warrants for seizure of the film and for petitioner's arrest on the ground that the film was obscene. Exhibition of an obscene film violates New York …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"op":1,"ar":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"0":"32, 33","1":"20, 21","2":"9, 13, 14"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"op":3,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"11, 28","1":"6, 25, 30, 31","2":"8, 11, 17"}},{"t":"case","label":"Jahjaga v. Attorney Gen.","cite":"512 F.3d 80","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/512/80/","by":{"0":"37"}},{"t":"case","label":"Kawashima v. Holder","cite":"132 S. Ct. 1166","y":2012,"id":"2011/10-577","sc":1,"sum":"The Court held that filing a false tax return in violation of 26 U.S.C. Section 7206 qualifies as an aggravated felony under the Immigration and Nationality Act if the Government's revenue loss exceeds $10,000.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Kucana v. Holder","cite":"558 U.S. 233","y":2010,"id":"2009/08-911","sc":1,"op":1,"sum":"The Court held that 8 U.S.C. Section 1252(a)(2)(B)(ii) does not preclude federal courts from hearing cases specified by the Attorney General, only cases that are specified by statute.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Mach Mining, LLC v. EEOC","cite":"135 S. Ct. 1645","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1645/","sc":1,"by":{"0":"36, 37"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Moncrieffe v. Holder","cite":"569 U.S. 184","y":2013,"id":"2012/11-702","sc":1,"sum":"The Court found that distribution of small amounts of marijuana does not constitute an aggravated felony and thus, does not require deportation of the distributor.","sumSrc":"Oyez","by":{"0":"8, 9"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"sum":"The Court held that a court of appeals' decision to stay an alien's removal pending consideration of the alien's petition for review is governed by the 4-factor traditional test.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Reno v. Catholic Social Servs., Inc.","cite":"509 U.S. 43","y":1993,"id":"1992/91-1826","sc":1,"sum":"The record is insufficient to allow this Court to decide all issues necessary to determine whether the District Courts had jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"36, 37"}},{"t":"case","label":"Rodriguez-Roman v. INS","cite":"98 F.3d 416","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/98/416/","sum":"Noting “the importance of independent judicial review in an area [asylum] where administrative decisions can mean the difference between freedom and oppression and, quite possibly, life and death”.","sumSrc":"brief:0","by":{"0":"38"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Smith v. Berryhill","cite":"139 S. Ct. 1765","y":2019,"id":"2018/17-1606","sc":1,"sum":"A Social Security Administration Appeals Council dismissal on timeliness grounds of a request for review after a claimant has had an administrative law judge hearing on the merits qualifies as a “final decision . . . made after a hearing” for purposes of allowing judicial review under 42 U. S. C. §405(g).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"22, 36, 37"}},{"t":"case","label":"Sturgeon v. Frost","cite":"139 S. Ct. 1066","y":2019,"id":"2018/17-949","sc":1,"sum":"Alaska’s Nation River is not public land; and like all non-public lands and navigable waters within Alaska’s national parks, it is exempt under the Alaska National Interest Lands Conservation Act from the National Park Service’s ordinary regulatory authority.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"26"}},{"t":"case","label":"United States v. Nourse","cite":"34 U.S. 8","y":1835,"id":"scdb/1835-008","sc":1,"sum":"The treasury department of the United States, on the 14th of July 1829, issued a warrant of distress directed to the marshal of the District of Columbia, Commanding him to levy and collect, by distress and sale of his goods and chattels, a sum of money alleged to be due to the United States, on a treasury transcript, by Joseph Nourse, late register of the treasury. This warrant was issued in pursuance of the 3d and …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"36"}},{"t":"case","label":"Virginia Uranium, Inc. v. Warren","cite":"139 S. Ct. 1894","y":2019,"id":"2018/16-1275","sc":1,"sum":"The Fourth Circuit’s judgment that the Atomic Energy Act does not preempt Virginia’s prohibition on uranium mining in the Commonwealth is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24, 36"}},{"t":"case","label":"Zhang v. Gonzales","cite":"452 F.3d 167","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/452/167/","by":{"0":"39"}},{"t":"reg","label":"8 C.F.R. § 236.4","url":"https://www.ecfr.gov/current/title-8/section-236.4","subs":["(e)"],"by":{"0":"43"}},{"t":"reg","label":"8 C.F.R. § 1208.24","url":"https://www.ecfr.gov/current/title-8/section-1208.24","subs":["(b)(1)"],"by":{"0":"8"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(3)","(a)(43)(G)","(a)(47)(A)","(a)(47)(B)","(a)(47)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"4","1":"2, 8, 3, 24, 24","2":"2, 6, 10, 11"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(e)(2)(B)","(c)(1)(A)"],"stext":{"head":"§1229a. Removal proceedings","paras":[[0,"(a) Proceeding"],[0,"(1) In general"],[1,"An immigration judge shall conduct proceedings for deciding the inadmissibility or deportability of an alien."],[0,"(2) Charges"],[1,"An alien placed in proceedings under this section may be charged with any applicable ground of inadmissibility under section 1182(a) of this title or any applicable ground of deportability under section 1227(a) of this title."],[0,"(3) Exclusive procedures"],[1,"Unless otherwise specified in this chapter, a proceeding under this section shall be the sole and exclusive procedure for determining whether an alien may be admitted to the United States or, if the alien has been so admitted, removed from the United States. Nothing in this section shall affect proceedings conducted pursuant to section 1228 of this title."],[0,"(b) Conduct of proceeding"],[0,"(1) Authority of immigration judge"],[1,"The immigration judge shall administer oaths, receive evidence, and interrogate, examine, and cross-examine the alien and any witnesses. The immigration judge may issue subpoenas for the attendance of witnesses and presentation of evidence. The immigration judge shall have authority (under regulations prescribed by the Attorney General) to sanction by civil money penalty any action (or inaction) in contempt of the judge's proper exercise of authority under this chapter."],[0,"(2) Form of proceeding"],[0,"(A) In general"],[2,"The proceeding may take place—"],[3,"(i) in person,"],[3,"(ii) where agreed to by the parties, in the absence of the alien,"],[3,"(iii) through video conference, or"],[3,"(iv) subject to subparagraph (B), through telephone conference."],[0,"(B) Consent required in certain cases"],[2,"An evidentiary hearing on the merits may only be conducted through a telephone conference with the consent of the alien involved after the alien has been advised of the right to proceed in person or through video conference."],[0,"(3) Presence of alien"],[1,"If it is impracticable by reason of an alien's mental incompetency for the alien to be present at the proceeding, the Attorney General shall prescribe safeguards to protect the rights and privileges of the alien."],[0,"(4) Alien's rights in proceeding"],[1,"In proceedings under this section, under regulations of the Attorney General—"],[2,"(A) the alien shall have the privilege of being represented, at no expense to the Government, by counsel of the alien's choosing who is authorized to practice in such proceedings,"],[2,"(B) the alien shall have a reasonable opportunity to examine the evidence against the alien, to present evidence on the alien's own behalf, and to cross-examine witnesses presented by the Government but these rights shall not entitle the alien to examine such national security information as the Government may proffer in opposition to the alien's admission to the United States or to an application by the alien for discretionary relief under this chapter, and"],[2,"(C) a complete record shall be kept of all testimony and evidence produced at the proceeding."],[0,"(5) Consequences of failure to appear"],[0,"(A) In general"],[2,"Any alien who, after written notice required under paragraph (1) or (2) of section 1229(a) of this title has been provided to the alien or the alien's counsel of record, does not attend a proceeding under this section, shall be ordered removed in absentia if the Service establishes by clear, unequivocal, and convincing evidence that the written notice was so provided and that the alien is removable (as defined in subsection (e)(2)). The written notice by the Attorney General shall be considered sufficient for purposes of this subparagraph if provided at the most recent address provided under section 1229(a)(1)(F) of this title."],[0,"(B) No notice if failure to provide address information"],[2,"No written notice shall be required under subparagraph (A) if the alien has failed to provide the address required under section 1229(a)(1)(F) of this title."],[0,"(C) Rescission of order"],[2,"Such an order may be rescinded only—"],[3,"(i) upon a motion to reopen filed within 180 days after the date of the order of removal if the alien demonstrates that the failure to appear was because of exceptional circumstances (as defined in subsection (e)(1)), or"],[3,"(ii) upon a motion to reopen filed at any time if the alien demonstrates that the alien did not receive notice in accordance with paragraph (1) or (2) of section 1229(a) of this title or the alien demonstrates that the alien was in Federal or State custody and the failure to appear was through no fault of the alien."],[2,"The filing of the motion to reopen described in clause (i) or (ii) shall stay the removal of the alien pending disposition of the motion by the immigration judge."],[0,"(D) Effect on judicial review"],[2,"Any petition for review under section 1252 of this title of an order entered in absentia under this paragraph shall (except in cases described in section 1252(b)(5) of this title) be confined to (i) the validity of the notice provided to the alien, (ii) the reasons for the alien's not attending the proceeding, and (iii) whether or not the alien is removable."],[0,"(E) Additional application to certain aliens in contiguous territory"],[2,"The preceding provisions of this paragraph shall apply to all aliens placed in proceedings under this section, including any alien who remains in a contiguous foreign territory pursuant to section 1225(b)(2)(C) of this title."],[0,"(6) Treatment of frivolous behavior"],[1,"The Attorney General shall, by regulation—"],[2,"(A) define in a proceeding before an immigration judge or before an appellate administrative body under this subchapter, frivolous behavior for which attorneys may be sanctioned,"],[2,"(B) specify the circumstances under which an administrative appeal of a decision or ruling will be considered frivolous and will be summarily dismissed, and"],[2,"(C) impose appropriate sanctions (which may include suspension and disbarment) in the case of frivolous behavior."],[1,"Nothing in this paragraph shall be construed as limiting the authority of the Attorney General to take actions with respect to inappropriate behavior."],[0,"(7) Limitation on discretionary relief for failure to appear"],[1,"Any alien against whom a final order of removal is entered in absentia under this subsection and who, at the time of the notice described in paragraph (1) or (2) of section 1229(a) of this title, was provided oral notice, either in the alien's native language or in another language the alien understands, of the time and place of the proceedings and of the consequences under this paragraph of failing, other than because of exceptional circumstances (as defined in subsection (e)(1)) to attend a proceeding under this section, shall not be eligible for relief under section 1229b, 1229c, 1255, 1258, or 1259 of this title for a period of 10 years after the date of the entry of the final order of removal."],[0,"(c) Decision and burden of proof"],[0,"(1) Decision"],[0,"(A) In general"],[2,"At the conclusion of the proceeding the immigration judge shall decide whether an alien is removable from the United States. The determination of the immigration judge shall be based only on the evidence produced at the hearing."],[0,"(B) Certain medical decisions"],[2,"If a medical officer or civil surgeon or board of medical officers has certified under section 1222(b) of this title that an alien has a disease, illness, or addiction which would make the alien inadmissible under paragraph (1) of section 1182(a) of this title, the decision of the immigration judge shall be based solely upon such certification."],[0,"(2) Burden on alien"],[1,"In the proceeding the alien has the burden of establishing—"],[2,"(A) if the alien is an applicant for admission, that the alien is clearly and beyond doubt entitled to be admitted and is not inadmissible under section 1182 of this title; or"],[2,"(B) by clear and convincing evidence, that the alien is lawfully present in the United States pursuant to a prior admission."],[1,"In meeting the burden of proof under subparagraph (B), the alien shall have access to the alien's visa or other entry document, if any, and any other records and documents, not considered by the Attorney General to be confidential, pertaining to the alien's admission or presence in the United States."],[0,"(3) Burden on service in cases of deportable aliens"],[0,"(A) In general"],[2,"In the proceeding the Service has the burden of establishing by clear and convincing evidence that, in the case of an alien who has been admitted to the United States, the alien is deportable. No decision on deportability shall be valid unless it is based upon reasonable, substantial, and probative evidence."],[0,"(B) Proof of convictions"],[2,"In any proceeding under this chapter, any of the following documents or records (or a certified copy of such an official document or record) shall constitute proof of a criminal conviction:"],[3,"(i) An official record of judgment and conviction."],[3,"(ii) An official record of plea, verdict, and sentence."],[3,"(iii) A docket entry from court records that indicates the existence of the conviction."],[3,"(iv) Official minutes of a court proceeding or a transcript of a court hearing in which the court takes notice of the existence of the conviction."],[3,"(v) An abstract of a record of conviction prepared by the court in which the conviction was entered, or by a State official associated with the State's repository of criminal justice records, that indicates the charge or section of law violated, the disposition of the case, the existence and date of conviction, and the sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229a?type=usc&year=mostrecent&link-type=html"},"head":"§1229a. Removal proceedings","tname":"Aliens and Nationality","by":{"0":"3","1":"24"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"reg","label":"64 Fed. Reg. 8,478","url":"https://www.govinfo.gov/link/fr/64/8478","by":{"0":"6, 32, 42","1":"5, 6, 28"}},{"t":"reg","label":"82 Fed. Reg. 45,161","url":"https://www.govinfo.gov/link/fr/82/45161","by":{"0":"43"}},{"t":"reg","label":"84 Fed. Reg. 3,665","url":"https://www.govinfo.gov/link/fr/84/3665","by":{"0":"44"}},{"t":"reg","label":"84 Fed. Reg. 33,829","url":"https://www.govinfo.gov/link/fr/84/33829","by":{"0":"27, 43, 44"}},{"t":"law","label":"Rules, Regulations—continued, Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"passim","2":"2, 7"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"3, 11","1":"4","2":"7"}},{"t":"law","label":"Pub. L. No. 105-277","url":"https://www.govinfo.gov/link/plaw/105/public/277","by":{"0":"passim","1":"5, 27"}},{"t":"law","label":"Pub. L. No. 109-13","url":"https://www.govinfo.gov/link/plaw/109/public/13","by":{"0":"11, 20, 29, 30","1":"6","2":"3, 4 ,16"}},{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Agonafer v. Sessions","cite":"859 F.3d 1198","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/859/1198/","by":{"1":"40"}},{"t":"case","label":"Ahmed v. Mukasey","cite":"300 Fed. Appx. 324","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./300/324/","op":1,"by":{"1":"35"}},{"t":"case","label":"Al-Salehi v. INS","cite":"47 F.3d 390","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/47/390/","by":{"1":"21"}},{"t":"case","label":"Ali v. Mukasey","cite":"529 F.3d 478","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/529/478/","by":{"1":"36"}},{"t":"case","label":"Alphonsus v. Holder","cite":"705 F.3d 1031","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/705/1031/","by":{"1":"39"}},{"t":"case","label":"Bank of Am. Corp. v. City of Miami","cite":"137 S. Ct. 1296","y":2017,"id":"2016/15-1111","sc":1,"sum":"The Court determined that the “aggrieved persons” language of the Fair Housing Act (FHA) does not impose a more narrow standing standard than Article III does and allows a city to sue, but the proximate cause standard requires the plaintiffs to show more than the possibility that a defendant could have foreseen the harm.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Brotherhood of R.R. Trainmen, Enter. Lodge","cite":"321 U.S. 50","y":1944,"id":"scdb/1943-097","sc":1,"sum":"1. A railroad company which refused to submit a labor dispute to arbitration in accordance with provisions of the Railway Labor Act-although it had sought to settle the dispute by negotiation and by mediation-has not made \"every reasonable effort\" to settle the dispute, within the meaning of §8 of the Norris-LaGuardia Act, and is thereby barred from injunctive relief in the federal courts.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Brownell v. Tom We Shung","cite":"352 U.S. 180","y":1956,"id":"1956/43","sc":1,"sum":"Under § 10 of the Administrative Procedure Act, an alien whose exclusion has been ordered administratively under the Immigration and Nationality Act of 1952, and who neither claims citizenship nor holds a certificate of identity issued under § 360 (b) of that Act, may obtain judicial review of such order by an action in a federal district court for a declaratory judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2"}},{"t":"case","label":"Cadet v. Bulger","cite":"377 F.3d 1173","y":2004,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/377/1173/","by":{"1":"31","2":"17"}},{"t":"case","label":"Cheng Fan Kwok v. INS","cite":"392 U.S. 206","y":1968,"id":"1967/638","sc":1,"sum":"Jurisdietion to review the denial by a district dir(etor of immigration of a stlav of deportation, requested by a Chinese seaian'who had deserted his ship and remained unlawfully in this country, where the pertinent order was not entered in the course of a deportation proceeding conducted under §242 (b) of the Immigration and Nationality Act, is not, under the provisions of § 106 (a), vested exclusively in the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21","2":"13, 14"}},{"t":"case","label":"Cherichel v. Holder","cite":"591 F.3d 1002","y":2010,"url":"https://www.courtlistener.com/c/F.3d/591/1002/","by":{"1":"18"}},{"t":"case","label":"Chupina v. Holder","cite":"570 F.3d 99","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/570/99/","sum":"Recognizing that the “reasoning in Foti is equally applicable” to judicial review of “applications for CAT protection” in removal proceedings.","sumSrc":"brief:1","by":{"1":"25"}},{"t":"case","label":"Cochise Consultancy, Inc. v. United States ex rel. Hunt","cite":"139 S. Ct. 1507","y":2019,"id":"2018/18-315","sc":1,"sum":"The limitations period in 31 U. S. C. §3731(b)(2)—which provides that a False Claims Act action must be brought within 3 years after the “the official of the United States charged with responsibility to act in the circumstances” knew or should have known the relevant facts, but not more than 10 years after the violation—applies in a qui tam suit in which the Federal Government has declined to intervene; the relator in a nonintervened suit is not “the official of the United States” whose knowledge triggers §3731(b)(2)’s limitations period.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Cole v. U.S. Attorney Gen.","cite":"712 F.3d 517","y":2013,"url":"https://www.courtlistener.com/c/F.3d/712/517/","op":1,"by":{"1":"17"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Davis v. Michigan Dep’t of Treasury","cite":"489 U.S. 803","y":1989,"id":"1988/87-1020","sc":1,"sum":"Section 111 allows a state to tax income paid by the federal government \"if the taxation does not discriminate against the officer or employee because of the source of the pay or compensation.\" Because the Court found no \"significant differences between the two classes [federal and state employees],\" it held that the Michigan tax distinguished between employees solely on \"the source of the pay.\".","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Enwonwu v. Gonzáles","cite":"232 Fed. Appx. 11","y":2007,"court":"1st Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./232/11/","by":{"1":"36"}},{"t":"case","label":"Escudero-Arciniega v. Holder","cite":"702 F.3d 781","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/702/781/","op":1,"by":{"1":"17, 18"}},{"t":"case","label":"Garcia v. INS","cite":"7 F.3d 1320","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/7/1320/","by":{"1":"21"}},{"t":"case","label":"Garcia v. Lynch","cite":"798 F.3d 876","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/798/876/","by":{"1":"40"}},{"t":"case","label":"Gourdet v. Holder","cite":"587 F.3d 1","y":2009,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/587/1/","op":1,"by":{"1":"18"}},{"t":"case","label":"Henderson ex rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Home Depot U.S.A., Inc. v. Jackson","cite":"139 S. Ct. 1743","y":2019,"id":"2018/17-1471","sc":1,"sum":"Neither the general removal provision, 28 U. S. C. §1441(a), nor the removal provision in the Class Action Fairness Act of 2005, §1453(b), permit a third-party counterclaim defendant to remove a class-action claim from state to federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"16"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"INS v. Doherty","cite":"502 U.S. 314","y":1992,"id":"1991/90-925","sc":1,"sum":"The judgment is reversed. 908 F. 2d 1108, reversed. THE CHIEF JUSTICE delivered the opinion of the Court with respect to Part I, concluding that the Attorney General did not abuse his discreCite as: 502 U. S. 314 (1992) tion in denying the motion to reopen Doherty's deportation proceedings. There is no statutory provision for reopening, and the authority for such motions derives solely from regulations promulgated …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"INS v. Elias-Zacarias","cite":"502 U.S. 478","y":1992,"id":"1991/90-1342","sc":1,"op":1,"sum":"A guerrilla organization's attempt to coerce a person into performing military service does not necessarily constitute \"persecution on account of... political opinion\" under § 101(a)(42) of the Immigration and Nationality Act, 8 U. S. C. §1101(a)(42). Even one who supports the political aims of a guerrilla movement might resist military combat and thus become the object of such coercion. Moreover, persecution on …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Ilchuk v. Attorney Gen. of the U.S.","cite":"434 F.3d 618","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/434/618/","by":{"1":"18"}},{"t":"case","label":"Ishak v. Gonzales","cite":"422 F.3d 22","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/422/22/","by":{"1":"32","2":"16"}},{"t":"case","label":"Issaq v. Holder","cite":"617 F.3d 962","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/617/962/","by":{"1":"41, 42"}},{"t":"case","label":"Keungne v. U.S. Attorney Gen.","cite":"561 F.3d 1281","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/561/1281/","op":1,"by":{"1":"11, 12","2":"21"}},{"t":"case","label":"Kofa v. INS","cite":"60 F.3d 1084","y":1995,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/60/1084/","by":{"1":"21"}},{"t":"case","label":"Kouambo v. Barr","cite":"943 F.3d 205","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/943/205/","op":1,"by":{"1":"26"}},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"138 S. Ct. 1752","y":2018,"id":"2017/16-1215","sc":1,"sum":"The Court decided that a statement regarding a specific asset can be a “statement respecting the debtor’s . . . financial condition” under section 523(a)(2)(B) of the Bankruptcy Code.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Law v. Siegel","cite":"571 U.S. 415","y":2014,"id":"2013/12-5196","sc":1,"sum":"The Court found that a bankruptcy court may not enforce specific statutory exceptions.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Lenjinac v. Holder","cite":"780 F.3d 852","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/780/852/","by":{"1":"41"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"sum":"Yes. Although the ADEA does not expressly provide for jury trials, its structure shows that Congress intended a jury to be available in private ADEA actions when a party seeks one. The Court therefore did not reach the Seventh Amendment question.","sumSrc":"AI-generated brief","by":{"1":"22","2":"10"}},{"t":"case","label":"Lovan v. Holder","cite":"574 F.3d 990","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/574/990/","op":2,"by":{"1":"33, 35","2":"4"}},{"t":"case","label":"Luna-Garcia v. Holder","cite":"777 F.3d 1182","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/777/1182/","by":{"1":"36"}},{"t":"case","label":"Mansoori v. INS","cite":"32 F.3d 1020","y":1994,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/32/1020/","by":{"1":"21"}},{"t":"case","label":"Medrano-Olivas v. Holder","cite":"590 Fed. Appx. 770","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./590/770/","by":{"1":"18"}},{"t":"case","label":"Mosquera-Perez v. INS","cite":"3 F.3d 553","y":1993,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/3/553/","by":{"1":"21"}},{"t":"case","label":"Ogbudimkpa v. Ashcroft","cite":"342 F.3d 207","y":2003,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/342/207/","by":{"1":"31"}},{"t":"case","label":"Omar v. McHugh","cite":"646 F.3d 13","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/646/13/","by":{"1":"33"}},{"t":"case","label":"Ortiz-Alfaro v. Holder","cite":"694 F.3d 955","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/694/955/","by":{"1":"36"}},{"t":"case","label":"Ortiz-Franco v. Holder","cite":"782 F.3d 81","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/782/81/","op":2,"sum":"Explaining that Section 1252(a)(4) “simply serves to ‘confirm[]’ that the statutory right to judicial review exists only as part of a review of a final order of removal”.","sumSrc":"brief:1","by":{"1":"17, 32, 35, 42","2":"4"}},{"t":"case","label":"Patchak v. Zinke","cite":"138 S. Ct. 897","y":2018,"id":"2017/16-498","sc":1,"sum":"The Court held that a statute that directs the federal courts to \"promptly dismiss” certain lawsuits without affecting any underlying laws does not violate the Constitution’s separation of powers principles.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Pechenkov v. Holder","cite":"705 F.3d 444","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/705/444/","op":1,"by":{"1":"39, 40, 41"}},{"t":"case","label":"Ponce-Osorio v. Johnson","cite":"824 F.3d 502","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/824/502/","by":{"1":"36"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"sum":"To give effect to § 5322(a)'s \"willfulness\" requirement, the Government must prove that the defendant acted with knowledge that the structuring he or she undertook was unlawful, not simply that the defendant's purpose was to circumvent a bank's reporting obligation. Section 5324 itself forbids structuring with a \"purpose of evading the [§ 5313(a)] reporting requirements,\" and the lower courts erred in treating the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Comm.","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"op":1,"sum":"Stating that the zipper clause applies to the “many . . . decisions or actions that may be part of the [removal] process”.","sumSrc":"opinion","by":{"1":"37"}},{"t":"case","label":"Reno v. Bossier Parish Sch. Bd.","cite":"528 U.S. 320","y":2000,"id":"1998/98-405","sc":1,"sum":"The Court held that section 5 does not prohibit preclearance of a redistricting plan enacted with a discriminatory but nonretrogressive purpose. \"As we have repeatedly noted, in vote-dilution cases [section 5] prevents nothing but backsliding, and preclearance under [section 5] affirms nothing but the absence of backsliding,\" wrote Justice Scalia.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Saint Fort v. Ashcroft","cite":"329 F.3d 191","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/329/191/","by":{"1":"31"}},{"t":"case","label":"Saintha v. Mukasey","cite":"516 F.3d 243","y":2008,"url":"https://www.courtlistener.com/c/F.3d/516/243/","by":{"1":"18"}},{"t":"case","label":"Scenic Am., Inc. v. United States Dep’t of Transp.","cite":"836 F.3d 42","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/836/42/","by":{"1":"12"}},{"t":"case","label":"Shabo v. Sessions","cite":"892 F.3d 237","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/892/237/","by":{"1":"36"}},{"t":"case","label":"Shaughnessy v. Pedreiro","cite":"349 U.S. 48","y":1955,"id":"scdb/1954-069","sc":1,"sum":"1. Under § 10 of the Administrative Procedure Act, an alien whose deportation has been ordered administratively under the Immigration and Nationality Act of 1952 may obtain a judicial review of such order by an action in a federal district court for a declaratory judgment and injunctive relief.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2"}},{"t":"case","label":"Singh v. Ashcroft","cite":"351 F.3d 435","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/351/435/","by":{"1":"31"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"ar":1,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"Ventura-Reyes v. Lynch","cite":"797 F.3d 348","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/797/348/","by":{"1":"17, 42"}},{"t":"case","label":"Wang v. Ashcroft","cite":"320 F.3d 130","y":2003,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/320/130/","by":{"1":"31"}},{"t":"case","label":"Wanjiru v. Holder","cite":"705 F.3d 258","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/705/258/","op":2,"ar":1,"by":{"1":"41","2":"21"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"42","2":"21"}},{"t":"usc","label":"8 U.S.C. § 1105a","url":"https://www.law.cornell.edu/uscode/text/8/1105a","subs":["(1964)","(1982)","(a)(1964)"],"by":{"1":"20, 22, 21, 2"}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","subs":["(b)(2)(A)(ii)"],"by":{"1":"8, 8"}},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(b)(1)"],"stext":{"head":"§1225. Inspection by immigration officers; expedited removal of inadmissible arriving aliens; referral for hearing","paras":[[0,"(a) Inspection"],[0,"(1) Aliens treated as applicants for admission"],[1,"An alien present in the United States who has not been admitted or who arrives in the United States (whether or not at a designated port of arrival and including an alien who is brought to the United States after having been interdicted in international or United States waters) shall be deemed for purposes of this chapter an applicant for admission."],[0,"(2) Stowaways"],[1,"An arriving alien who is a stowaway is not eligible to apply for admission or to be admitted and shall be ordered removed upon inspection by an immigration officer. Upon such inspection if the alien indicates an intention to apply for asylum under section 1158 of this title or a fear of persecution, the officer shall refer the alien for an interview under subsection (b)(1)(B). A stowaway may apply for asylum only if the stowaway is found to have a credible fear of persecution under subsection (b)(1)(B). In no case may a stowaway be considered an applicant for admission or eligible for a hearing under section 1229a of this title."],[0,"(3) Inspection"],[1,"All aliens (including alien crewmen) who are applicants for admission or otherwise seeking admission or readmission to or transit through the United States shall be inspected by immigration officers."],[0,"(4) Withdrawal of application for admission"],[1,"An alien applying for admission may, in the discretion of the Attorney General and at any time, be permitted to withdraw the application for admission and depart immediately from the United States."],[0,"(5) Statements"],[1,"An applicant for admission may be required to state under oath any information sought by an immigration officer regarding the purposes and intentions of the applicant in seeking admission to the United States, including the applicant's intended length of stay and whether the applicant intends to remain permanently or become a United States citizen, and whether the applicant is inadmissible."],[0,"(b) Inspection of applicants for admission"],[0,"(1) Inspection of aliens arriving in the United States and certain other aliens who have not been admitted or paroled"],[0,"(A) Screening"],[0,"(i) In general"],[3,"If an immigration officer determines that an alien (other than an alien described in subparagraph (F)) who is arriving in the United States or is described in clause (iii) is inadmissible under section 1182(a)(6)(C) or 1182(a)(7) of this title, the officer shall order the alien removed from the United States without further hearing or review unless the alien indicates either an intention to apply for asylum under section 1158 of this title or a fear of persecution."],[0,"(ii) Claims for asylum"],[3,"If an immigration officer determines that an alien (other than an alien described in subparagraph (F)) who is arriving in the United States or is described in clause (iii) is inadmissible under section 1182(a)(6)(C) or 1182(a)(7) of this title and the alien indicates either an intention to apply for asylum under section 1158 of this title or a fear of persecution, the officer shall refer the alien for an interview by an asylum officer under subparagraph (B)."],[0,"(iii) Application to certain other aliens"],[0,"(I) In general"],[4,"The Attorney General may apply clauses (i) and (ii) of this subparagraph to any or all aliens described in subclause (II) as designated by the Attorney General. Such designation shall be in the sole and unreviewable discretion of the Attorney General and may be modified at any time."],[0,"(II) Aliens described"],[4,"An alien described in this clause is an alien who is not described in subparagraph (F), who has not been admitted or paroled into the United States, and who has not affirmatively shown, to the satisfaction of an immigration officer, that the alien has been physically present in the United States continuously for the 2-year period immediately prior to the date of the determination of inadmissibility under this subparagraph."],[0,"(B) Asylum interviews"],[0,"(i) Conduct by asylum officers"],[3,"An asylum officer shall conduct interviews of aliens referred under subparagraph (A)(ii), either at a port of entry or at such other place designated by the Attorney General."],[0,"(ii) Referral of certain aliens"],[3,"If the officer determines at the time of the interview that an alien has a credible fear of persecution (within the meaning of clause (v)), the alien shall be detained for further consideration of the application for asylum."],[0,"(iii) Removal without further review if no credible fear of persecution"],[0,"(I) In general"],[4,"Subject to subclause (III), if the officer determines that an alien does not have a credible fear of persecution, the officer shall order the alien removed from the United States without further hearing or review."],[0,"(II) Record of determination"],[4,"The officer shall prepare a written record of a determination under subclause (I). Such record shall include a summary of the material facts as stated by the applicant, such additional facts (if any) relied upon by the officer, and the officer's analysis of why, in the light of such facts, the alien has not established a credible fear of persecution. A copy of the officer's interview notes shall be attached to the written summary."],[0,"(III) Review of determination"],[4,"The Attorney General shall provide by regulation and upon the alien's request for prompt review by an immigration judge of a determination under subclause (I) that the alien does not have a credible fear of persecution. Such review shall include an opportunity for the alien to be heard and questioned by the immigration judge, either in person or by telephonic or video connection. Review shall be concluded as expeditiously as possible, to the maximum extent practicable within 24 hours, but in no case later than 7 days after the date of the determination under subclause (I)."],[0,"(IV) Mandatory detention"],[4,"Any alien subject to the procedures under this clause shall be detained pending a final determination of credible fear of persecution and, if found not to have such a fear, until removed."],[0,"(iv) Information about interviews"],[3,"The Attorney General shall provide information concerning the asylum interview described in this subparagraph to aliens who may be eligible. An alien who is eligible for such interview may consult with a person or persons of the alien's choosing prior to the interview or any review thereof, according to regulations prescribed by the Attorney General. Such consultation shall be at no expense to the Government and shall not unreasonably delay the process."],[0,"(v) \"Credible fear of persecution\" defined"],[3,"For purposes of this subparagraph, the term \"credible fear of persecution\" means that there is a significant possibility, taking into account the credibility of the statements made by the alien in support of the alien's claim and such other facts as are known to the officer, that the alien could establish eligibility for asylum under section 1158 of this title."],[0,"(C) Limitation on administrative review"],[2,"Except as provided in subparagraph (B)(iii)(III), a removal order entered in accordance with subparagraph (A)(i) or (B)(iii)(I) is not subject to administrative appeal, except that the Attorney General shall provide by regulation for prompt review of such an order under subparagraph (A)(i) against an alien who claims under oath, or as permitted under penalty of perjury under section 1746 of title 28, after having been warned of the penalties for falsely making such claim under such conditions, to have been lawfully admitted for permanent residence, to have been admitted as a refugee under section 1157 of this title, or to have been granted asylum under section 1158 of this title."],[0,"(D) Limit on collateral attacks"],[2,"In any action brought against an alien under section 1325(a) of this title or section 1326 of this title, the court shall not have jurisdiction to hear any claim attacking the validity of an order of removal entered under subparagraph (A)(i) or (B)(iii)."],[0,"(E) \"Asylum officer\" defined"],[2,"As used in this paragraph, the term \"asylum officer\" means an immigration officer who—"],[3,"(i) has had professional training in country conditions, asylum law, and interview techniques comparable to that provided to full-time adjudicators of applications under section 1158 of this title, and"],[3,"(ii) is supervised by an officer who meets the condition described in clause (i) and has had substantial experience adjudicating asylum applications."],[0,"(F) Exception"],[2,"Subparagraph (A) shall not apply to an alien who is a native or citizen of a country in the Western Hemisphere with whose government the United States does not have full diplomatic relations and who arrives by aircraft at a port of entry."],[0,"(G) Commonwealth of the Northern Mariana Islands"],[2,"Nothing in this subsection shall be construed to authorize or require any person described in section 1158(e) of this title to be permitted to apply for asylum under section 1158 of this title at any time before January 1, 2014."],[0,"(2) Inspection of other aliens"],[0,"(A) In general"],[2,"Subject to subparagraphs (B) and (C), in the case of an alien who is an applicant for admission, if the examining immigration officer determines that an alien seeking admission is not clearly and beyond a doubt entitled to be admitted, the alien shall be detained for a proceeding under section 1229a of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1225?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1225. Inspection by immigration officers; expedited removal of inadmissible arriving aliens; referral for hearing","tname":"Aliens and Nationality","by":{"1":"30"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","subs":["(a)(2)(A)(i)","(a)(2)(A)(iii)"],"stext":{"head":"§1227. Deportable aliens","paras":[[0,"(a) Classes of deportable aliens"],[0,"Any alien (including an alien crewman) in and admitted to the United States shall, upon the order of the Attorney General, be removed if the alien is within one or more of the following classes of deportable aliens:"],[0,"(1) Inadmissible at time of entry or of adjustment of status or violates status"],[0,"(A) Inadmissible aliens"],[2,"Any alien who at the time of entry or adjustment of status was within one or more of the classes of aliens inadmissible by the law existing at such time is deportable."],[0,"(B) Present in violation of law"],[2,"Any alien who is present in the United States in violation of this chapter or any other law of the United States, or whose nonimmigrant visa (or other documentation authorizing admission into the United States as a nonimmigrant) has been revoked under section 1201(i) of this title, is deportable."],[0,"(C) Violated nonimmigrant status or condition of entry"],[0,"(i) Nonimmigrant status violators"],[3,"Any alien who was admitted as a nonimmigrant and who has failed to maintain the nonimmigrant status in which the alien was admitted or to which it was changed under section 1258 of this title, or to comply with the conditions of any such status, is deportable."],[0,"(ii) Violators of conditions of entry"],[3,"Any alien whom the Secretary of Health and Human Services certifies has failed to comply with terms, conditions, and controls that were imposed under section 1182(g) of this title is deportable."],[0,"(D) Termination of conditional permanent residence"],[0,"(i) In general"],[3,"Any alien with permanent resident status on a conditional basis under section 1186a of this title (relating to conditional permanent resident status for certain alien spouses and sons and daughters) or under section 1186b of this title (relating to conditional permanent resident status for certain alien entrepreneurs, spouses, and children) who has had such status terminated under such respective section is deportable."],[0,"(ii) Exception"],[3,"Clause (i) shall not apply in the cases described in section 1186a(c)(4) of this title (relating to certain hardship waivers)."],[0,"(E) Smuggling"],[0,"(i) In general"],[3,"Any alien who (prior to the date of entry, at the time of any entry, or within 5 years of the date of any entry) knowingly has encouraged, induced, assisted, abetted, or aided any other alien to enter or to try to enter the United States in violation of law is deportable."],[0,"(ii) Special rule in the case of family reunification"],[3,"Clause (i) shall not apply in the case of alien who is an eligible immigrant (as defined in section 301(b)(1) of the Immigration Act of 1990), was physically present in the United States on May 5, 1988, and is seeking admission as an immediate relative or under section 1153(a)(2) of this title (including under section 112 of the Immigration Act of 1990) or benefits under section 301(a) of the Immigration Act of 1990 if the alien, before May 5, 1988, has encouraged, induced, assisted, abetted, or aided only the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(iii) Waiver authorized"],[3,"The Attorney General may, in his discretion for humanitarian purposes, to assure family unity, or when it is otherwise in the public interest, waive application of clause (i) in the case of any alien lawfully admitted for permanent residence if the alien has encouraged, induced, assisted, abetted, or aided only an individual who at the time of the offense was the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(F) Repealed. Pub. L. 104–208, div. C, title VI, §671(d)(1)(C), Sept. 30, 1996, 110 Stat. 3009–723"],[0,"(G) Marriage fraud"],[2,"An alien shall be considered to be deportable as having procured a visa or other documentation by fraud (within the meaning of section 1182(a)(6)(C)(i) of this title) and to be in the United States in violation of this chapter (within the meaning of subparagraph (B)) if—"],[3,"(i) the alien obtains any admission into the United States with an immigrant visa or other documentation procured on the basis of a marriage entered into less than 2 years prior to such admission of the alien and which, within 2 years subsequent to any admission of the alien in the United States, shall be judicially annulled or terminated, unless the alien establishes to the satisfaction of the Attorney General that such marriage was not contracted for the purpose of evading any provisions of the immigration laws, or"],[3,"(ii) it appears to the satisfaction of the Attorney General that the alien has failed or refused to fulfill the alien's marital agreement which in the opinion of the Attorney General was made for the purpose of procuring the alien's admission as an immigrant."],[0,"(H) Waiver authorized for certain misrepresentations"],[2,"The provisions of this paragraph relating to the removal of aliens within the United States on the ground that they were inadmissible at the time of admission as aliens described in section 1182(a)(6)(C)(i) of this title, whether willful or innocent, may, in the discretion of the Attorney General, be waived for any alien (other than an alien described in paragraph (4)(D)) who—"],[3,"(i)(I) is the spouse, parent, son, or daughter of a citizen of the United States or of an alien lawfully admitted to the United States for permanent residence; and"],[3,"(II) was in possession of an immigrant visa or equivalent document and was otherwise admissible to the United States at the time of such admission except for those grounds of inadmissibility specified under paragraphs (5)(A) and (7)(A) of section 1182(a) of this title which were a direct result of that fraud or misrepresentation."],[3,"(ii) is a VAWA self-petitioner."],[2,"A waiver of removal for fraud or misrepresentation granted under this subparagraph shall also operate to waive removal based on the grounds of inadmissibility directly resulting from such fraud or misrepresentation."],[0,"(2) Criminal offenses"],[0,"(A) General crimes"],[0,"(i) Crimes of moral turpitude"],[3,"Any alien who—"],[4,"(I) is convicted of a crime involving moral turpitude committed within five years (or 10 years in the case of an alien provided lawful permanent resident status under section 1255(j) of this title) after the date of admission, and"],[4,"(II) is convicted of a crime for which a sentence of one year or longer may be imposed,"],[0,"is deportable."],[0,"(ii) Multiple criminal convictions"],[3,"Any alien who at any time after admission is convicted of two or more crimes involving moral turpitude, not arising out of a single scheme of criminal misconduct, regardless of whether confined therefor and regardless of whether the convictions were in a single trial, is deportable."],[0,"(iii) Aggravated felony"],[3,"Any alien who is convicted of an aggravated felony at any time after admission is deportable."],[0,"(iv) High speed flight"],[3,"Any alien who is convicted of a violation of section 758 of title 18 (relating to high speed flight from an immigration checkpoint) is deportable."],[0,"(v) Failure to register as a sex offender"],[3,"Any alien who is convicted under section 2250 of title 18 is deportable."],[0,"(vi) Waiver authorized"],[3,"Clauses (i), (ii), (iii), and (iv) shall not apply in the case of an alien with respect to a criminal conviction if the alien subsequent to the criminal conviction has been granted a full and unconditional pardon by the President of the United States or by the Governor of any of the several States."],[0,"(B) Controlled substances"],[0,"(i) Conviction"],[3,"Any alien who at any time after admission has been convicted of a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21), other than a single offense involving possession for one's own use of 30 grams or less of marijuana, is deportable."],[0,"(ii) Drug abusers and addicts"],[3,"Any alien who is, or at any time after admission has been, a drug abuser or addict is deportable."],[0,"(C) Certain firearm offenses"],[2,"Any alien who at any time after admission is convicted under any law of purchasing, selling, offering for sale, exchanging, using, owning, possessing, or carrying, or of attempting or conspiring to purchase, sell, offer for sale, exchange, use, own, possess, or carry, any weapon, part, or accessory which is a firearm or destructive device (as defined in section 921(a) of title 18) in violation of any law is deportable."],[0,"(D) Miscellaneous crimes"],[2,"Any alien who at any time has been convicted (the judgment on such conviction becoming final) of, or has been so convicted of a conspiracy or attempt to violate—"],[3,"(i) any offense under chapter 37 (relating to espionage), chapter 105 (relating to sabotage), or chapter 115 (relating to treason and sedition) of title 18 for which a term of imprisonment of five or more years may be imposed;"],[3,"(ii) any offense under section 871 or 960 of title 18;"],[3,"(iii) a violation of any provision of the Military Selective Service Act (50 U.S.C. App. 451 et seq.) [now 50 U.S.C. 3801 et seq.] or the Trading With the Enemy Act (50 U.S.C. App. 1 et seq.) [now 50 U.S.C. 4301 et seq.]; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1227?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1227. Deportable aliens","tname":"Aliens and Nationality","by":{"1":"8, 11, 12, 8"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(a)(5)","(b)(3)","(b)(3)(B)(ii)"],"stext":{"head":"§1231. Detention and removal of aliens ordered removed","paras":[[0,"(a) Detention, release, and removal of aliens ordered removed"],[0,"(1) Removal period"],[0,"(A) In general"],[2,"Except as otherwise provided in this section, when an alien is ordered removed, the Attorney General shall remove the alien from the United States within a period of 90 days (in this section referred to as the \"removal period\")."],[0,"(B) Beginning of period"],[2,"The removal period begins on the latest of the following:"],[3,"(i) The date the order of removal becomes administratively final."],[3,"(ii) If the removal order is judicially reviewed and if a court orders a stay of the removal of the alien, the date of the court's final order."],[3,"(iii) If the alien is detained or confined (except under an immigration process), the date the alien is released from detention or confinement."],[0,"(C) Suspension of period"],[2,"The removal period shall be extended beyond a period of 90 days and the alien may remain in detention during such extended period if the alien fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure or conspires or acts to prevent the alien's removal subject to an order of removal."],[0,"(2) Detention"],[1,"During the removal period, the Attorney General shall detain the alien. Under no circumstance during the removal period shall the Attorney General release an alien who has been found inadmissible under section 1182(a)(2) or 1182(a)(3)(B) of this title or deportable under section 1227(a)(2) or 1227(a)(4)(B) of this title."],[0,"(3) Supervision after 90-day period"],[1,"If the alien does not leave or is not removed within the removal period, the alien, pending removal, shall be subject to supervision under regulations prescribed by the Attorney General. The regulations shall include provisions requiring the alien—"],[2,"(A) to appear before an immigration officer periodically for identification;"],[2,"(B) to submit, if necessary, to a medical and psychiatric examination at the expense of the United States Government;"],[2,"(C) to give information under oath about the alien's nationality, circumstances, habits, associations, and activities, and other information the Attorney General considers appropriate; and"],[2,"(D) to obey reasonable written restrictions on the alien's conduct or activities that the Attorney General prescribes for the alien."],[0,"(4) Aliens imprisoned, arrested, or on parole, supervised release, or probation"],[0,"(A) In general"],[2,"Except as provided in section 259(a) 1 of title 42 and paragraph (2),2 the Attorney General may not remove an alien who is sentenced to imprisonment until the alien is released from imprisonment. Parole, supervised release, probation, or possibility of arrest or further imprisonment is not a reason to defer removal."],[0,"(B) Exception for removal of nonviolent offenders prior to completion of sentence of imprisonment"],[2,"The Attorney General is authorized to remove an alien in accordance with applicable procedures under this chapter before the alien has completed a sentence of imprisonment—"],[3,"(i) in the case of an alien in the custody of the Attorney General, if the Attorney General determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense related to smuggling or harboring of aliens or an offense described in section 1101(a)(43)(B), (C), (E), (I), or (L) of this title 3 and (II) the removal of the alien is appropriate and in the best interest of the United States; or"],[3,"(ii) in the case of an alien in the custody of a State (or a political subdivision of a State), if the chief State official exercising authority with respect to the incarceration of the alien determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense described in section 1101(a)(43)(C) or (E) of this title), (II) the removal is appropriate and in the best interest of the State, and (III) submits a written request to the Attorney General that such alien be so removed."],[0,"(C) Notice"],[2,"Any alien removed pursuant to this paragraph shall be notified of the penalties under the laws of the United States relating to the reentry of deported aliens, particularly the expanded penalties for aliens removed under subparagraph (B)."],[0,"(D) No private right"],[2,"No cause or claim may be asserted under this paragraph against any official of the United States or of any State to compel the release, removal, or consideration for release or removal of any alien."],[0,"(5) Reinstatement of removal orders against aliens illegally reentering"],[1,"If the Attorney General finds that an alien has reentered the United States illegally after having been removed or having departed voluntarily, under an order of removal, the prior order of removal is reinstated from its original date and is not subject to being reopened or reviewed, the alien is not eligible and may not apply for any relief under this chapter, and the alien shall be removed under the prior order at any time after the reentry."],[0,"(6) Inadmissible or criminal aliens"],[1,"An alien ordered removed who is inadmissible under section 1182 of this title, removable under section 1227(a)(1)(C), 1227(a)(2), or 1227(a)(4) of this title or who has been determined by the Attorney General to be a risk to the community or unlikely to comply with the order of removal, may be detained beyond the removal period and, if released, shall be subject to the terms of supervision in paragraph (3)."],[0,"(7) Employment authorization"],[1,"No alien ordered removed shall be eligible to receive authorization to be employed in the United States unless the Attorney General makes a specific finding that—"],[2,"(A) the alien cannot be removed due to the refusal of all countries designated by the alien or under this section to receive the alien, or"],[2,"(B) the removal of the alien is otherwise impracticable or contrary to the public interest."],[0,"(b) Countries to which aliens may be removed"],[0,"(1) Aliens arriving at the United States"],[1,"Subject to paragraph (3)—"],[0,"(A) In general"],[2,"Except as provided by subparagraphs (B) and (C), an alien who arrives at the United States and with respect to whom proceedings under section 1229a of this title were initiated at the time of such alien's arrival shall be removed to the country in which the alien boarded the vessel or aircraft on which the alien arrived in the United States."],[0,"(B) Travel from contiguous territory"],[2,"If the alien boarded the vessel or aircraft on which the alien arrived in the United States in a foreign territory contiguous to the United States, an island adjacent to the United States, or an island adjacent to a foreign territory contiguous to the United States, and the alien is not a native, citizen, subject, or national of, or does not reside in, the territory or island, removal shall be to the country in which the alien boarded the vessel that transported the alien to the territory or island."],[0,"(C) Alternative countries"],[2,"If the government of the country designated in subparagraph (A) or (B) is unwilling to accept the alien into that country's territory, removal shall be to any of the following countries, as directed by the Attorney General:"],[3,"(i) The country of which the alien is a citizen, subject, or national."],[3,"(ii) The country in which the alien was born."],[3,"(iii) The country in which the alien has a residence."],[3,"(iv) A country with a government that will accept the alien into the country's territory if removal to each country described in a previous clause of this subparagraph is impracticable, inadvisable, or impossible."],[0,"(2) Other aliens"],[1,"Subject to paragraph (3)—"],[0,"(A) Selection of country by alien"],[2,"Except as otherwise provided in this paragraph—"],[3,"(i) any alien not described in paragraph (1) who has been ordered removed may designate one country to which the alien wants to be removed, and"],[3,"(ii) the Attorney General shall remove the alien to the country the alien so designates."],[0,"(B) Limitation on designation"],[2,"An alien may designate under subparagraph (A)(i) a foreign territory contiguous to the United States, an adjacent island, or an island adjacent to a foreign territory contiguous to the United States as the place to which the alien is to be removed only if the alien is a native, citizen, subject, or national of, or has resided in, that designated territory or island."],[0,"(C) Disregarding designation"],[2,"The Attorney General may disregard a designation under subparagraph (A)(i) if—"],[3,"(i) the alien fails to designate a country promptly;"],[3,"(ii) the government of the country does not inform the Attorney General finally, within 30 days after the date the Attorney General first inquires, whether the government will accept the alien into the country;"],[3,"(iii) the government of the country is not willing to accept the alien into the country; or"],[3,"(iv) the Attorney General decides that removing the alien to the country is prejudicial to the United States."],[0,"(D) Alternative country"],[2,"If an alien is not removed to a country designated under subparagraph (A)(i), the Attorney General shall remove the alien to a country of which the alien is a subject, national, or citizen unless the government of the country—"],[3,"(i) does not inform the Attorney General or the alien finally, within 30 days after the date the Attorney General first inquires or within another period of time the Attorney General decides is reasonable, whether the government will accept the alien into the country; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1231?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1231. Detention and removal of aliens ordered removed","tname":"Aliens and Nationality","by":{"1":"5, 36, 25, 25"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)","(a)(1)","(a)(2)(C)","(a)(2)(D)","(a)(4)","(a)(5)","(b)(1)","(b)(4)(B)","(b)(9)","(e)","(g)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"op":15,"ar":9,"head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"1":"25, 25, 25, 25, 25, 25, 25, 25, 25, 25, 25, 25"}},{"t":"usc","label":"8 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/8/1253","subs":["(h)(1958)"],"by":{"1":"25"}},{"t":"usc","label":"8 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/8/1254","subs":["(a)(4)(1958)"],"by":{"1":"19"}},{"t":"usc","label":"18 U.S.C. § 21","url":"https://www.law.cornell.edu/uscode/text/18/21","by":{"1":"7"}},{"t":"usc","label":"18 U.S.C. § 2315","url":"https://www.law.cornell.edu/uscode/text/18/2315","by":{"1":"7"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","by":{"1":"18"}},{"t":"case","label":"Benslimane v. Gonzales","cite":"430 F.3d 828","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/430/828/","by":{"2":"19"}},{"t":"case","label":"Chen v. U.S. Dep’t of Justice","cite":"144 F. App’x 147","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/144/147/","by":{"2":"17"}},{"t":"case","label":"Department of Transp. v. Association of Am. Railroads","cite":"575 U.S. 43","y":2015,"id":"2014/13-1080","sc":1,"sum":"The Court held that for purposes of the validity of metrics and standards, Amtrak is a governmental entity.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"E.O.H.C. v. Secretary U.S. Dep’t Homeland Sec.","cite":"2020 WL 728629","y":2020,"court":"3d Cir. Feb. 13","by":{"2":"13, 18"}},{"t":"case","label":"Henderson v. United States","cite":"568 U.S. 266","y":2013,"id":"2012/11-9307","sc":1,"sum":"The Court held that the determination of “plain error” is made during the appellate review, not during the trial.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Hosseini v. Johnson","cite":"826 F.3d 354","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/826/354/","by":{"2":"13"}},{"t":"case","label":"Kamar v. Sessions","cite":"875 F.3d 811","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/875/811/","by":{"2":"20"}},{"t":"case","label":"Lee v. Gonzales","cite":"410 F.3d 778","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/410/778/","op":1,"by":{"2":"21"}},{"t":"case","label":"Lin Zheng v. Sessions","cite":"728 F. App’x 56","y":2018,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/728/56/","by":{"2":"20"}},{"t":"case","label":"Maldonado v. Lynch","cite":"786 F.3d 1155","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/786/1155/","by":{"2":"17"}},{"t":"case","label":"Mata v. Lynch","cite":"135 S. Ct. 2150","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/2150/","sc":1,"by":{"2":"21"}},{"t":"case","label":"Perez v. USCIS","cite":"774 F.3d 960","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/774/960/","by":{"2":"13"}},{"t":"case","label":"Ramsameachire v. Ashcroft","cite":"357 F.3d 169","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/357/169/","by":{"2":"9"}},{"t":"case","label":"Singh v. Ashcroft","cite":"398 F.3d 396","y":2005,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/398/396/","by":{"2":"9"}},{"t":"case","label":"Sivakaran v. Ashcroft","cite":"368 F.3d 1028","y":2004,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/368/1028/","by":{"2":"9"}},{"t":"case","label":"Subrata v. Attorney Gen. of U.S.","cite":"378 F. App’x 226","y":2010,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/378/226/","by":{"2":"17"}},{"t":"case","label":"Sure-Tan, Inc. v. NLRB","cite":"467 U.S. 883","y":1984,"id":"1983/82-945","sc":1,"sum":"The Court held that that the NLRB can act to protect the labor rights of illegal immigrants because it serves the broader purpose of labor to have all workers represented, regardless of immigration status. Precedent establishes that the Board can protect the rights of any employee. The petitioners’ actions illegally discouraged union activity and caused the deportation of their employees.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Tilley v. Gonzales","cite":"228 F. App’x 585","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/228/585/","by":{"2":"8"}},{"t":"case","label":"Trinidad y Garcia v. Thomas","cite":"683 F.3d 952","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/683/952/","by":{"2":"4"}},{"t":"case","label":"Vinh Tan Nguyen v. Holder","cite":"763 F.3d 1022","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/763/1022/","op":1,"by":{"2":"9"}},{"t":"case","label":"Yeremin v. Holder","cite":"738 F.3d 708","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/738/708/","op":1,"by":{"2":"21"}},{"t":"case","label":"Zelaya v. Holder","cite":"668 F.3d 159","y":2012,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/668/159/","by":{"2":"9"}},{"t":"reg","label":"8 C.F.R. § 1208.17","url":"https://www.ecfr.gov/current/title-8/section-1208.17","subs":["(b)(1)"],"by":{"2":"5"}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","by":{"2":"16"}}]};